const out = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const binary = item.binary || {};
  const attachments = [];
  for (const key of Object.keys(binary)) {
    if (key === 'mime') continue;
    const b = binary[key];
    if (b && b.fileName) attachments.push({ name: b.fileName, mimeType: b.mimeType || 'unknown', size: b.fileSize || 0 });
  }
  let bodyText = '';
  try {
    const bodyRaw = (json.body && json.body.content) || json.bodyPreview || '';
    bodyText = (typeof bodyRaw === 'string') ? bodyRaw.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim() : '';
  } catch (e) { bodyText = ''; }
  const fromAddr = (json.from && json.from.emailAddress) ? json.from.emailAddress.address : '';
  const fromName = (json.from && json.from.emailAddress && json.from.emailAddress.name) ? json.from.emailAddress.name : '';
  const toAddresses = (json.toRecipients || []).map(r => (r.emailAddress && r.emailAddress.address) || '').filter(Boolean).join('; ');
  out.push({ json: { id: json.id, internetMessageId: json.internetMessageId, subject: json.subject, fromName, fromEmail: fromAddr, toAddresses, receivedDateTime: json.receivedDateTime, bodyText: bodyText.slice(0, 6000), attachments } });
}
return out;

const out = [];
const model = || 'qwen3.5:latest';
const ollamaUrl = || 'http://127.0.0.1:11434/api/chat';
const systemPrompt = 'Eres un analista senior de ciberseguridad experto en email. Clasifica el correo y devuelve SOLO un JSON con este esquema exacto: {"verdict":"malicious|phishing|spam|benign","confidence":0-100,"risk_level":"low|medium|high|critical","summary":"resumen en espanol de 1-2 frases","reasons":["hallazgo1","hallazgo2"]}. Evalua suplantacion del remitente/dominio, urgimiento y presion, peticiones de pagos/claves/credenciales, enlaces sospechosos, adjuntos con doble extension, Reply-To distinto al From, autenticacion SPF/DKIM/DMARC de cabeceras. No marques falsos positivos sin evidencia concreta.';
for (const item of $input.all()) {
  const d = item.json;
  const attachBlock = ((d.attachments || []).map(a => '  - ' + a.name + ' (' + a.mimeType + ', ' + (a.size || 0) + ' B)')).join('\n') || '  (sin adjuntos)';
  const userContent = ['SUBJECT: ' + (d.subject || ''), 'FROM: ' + (d.fromName || '') + (d.fromEmail ? ' <' + d.fromEmail + '>' : ''), 'TO: ' + (d.toAddresses || ''), 'RECEIVED: ' + (d.receivedDateTime || ''), '', 'BODY:', (d.bodyText || '').slice(0, 5000), '', 'ATTACHMENTS:', attachBlock].join('\n');
  let parsed = null, raw = '';
  try {
    const payload = { model: model, format: 'json', stream: false, think: false, options: { temperature: 0, num_predict: 400 }, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userContent }] };
    const resp = await this.helpers.httpRequest({ method: 'POST', url: ollamaUrl, json: true, headers: { 'Content-Type': 'application/json' }, body: payload });
    raw = resp && resp.message ? resp.message.content : '';
    const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
    if (s >= 0 && e > s) parsed = JSON.parse(raw.slice(s, e + 1));
  } catch (err) { parsed = { verdict: 'error', confidence: 0, risk_level: 'unknown', summary: 'Error de Ollama: ' + (err.message || err), reasons: [] }; }
  const verdict = String((parsed && parsed.verdict) || 'unknown').toLowerCase();
  const risk = String((parsed && parsed.risk_level) || 'unknown').toLowerCase();
  const confidence = Number((parsed && parsed.confidence) || 0);
  const isThreat = ['phishing', 'malicious'].includes(verdict) || ['high', 'critical'].includes(risk);
  const reasons = (parsed && Array.isArray(parsed.reasons) ? parsed.reasons : []).map(String);
  const summary = (parsed && parsed.summary) || 'Sin resultado';
  const attachInfo = ((d.attachments || []).map(a => a.name)).join(', ') || 'ninguno';
  const replyTo = (d.toAddresses || d.fromEmail || '').split(';').map(s => s.trim()).filter(Boolean).join(',');
  const replySubject = 'RE: [' + verdict.toUpperCase() + '] Análisis - ' + (d.subject || 'correo');
  out.push({ json: { ...d, verdict, risk_level: risk, confidence, summary, reasons, isThreat, replyTo, replySubject, replyBody: '' } });
}
return out;

const data = $getWorkflowStaticData('global');
data.threads = data.threads || {};
const out = [];
for (const item of $input.all()) {
  const d = { ...item.json };
  const fromKey = String(d.fromEmail || 'none').toLowerCase();
  const list = data.threads[fromKey] || [];
  d.thread = list.slice(-8).reverse().map(t => '[' + t.verdict + '] ' + t.summary).join('\n');
  list.push({ at: new Date().toISOString(), verdict: d.verdict, summary: d.summary });
  if (list.length > 20) list.splice(0, list.length - 20);
  data.threads[fromKey] = list;
  data._last = { replyTo: d.replyTo, replySubject: d.replySubject, replyBody: d.replyBody, fromEmail: d.fromEmail };
  out.push({ json: d });
}
return out;

const data = $getWorkflowStaticData('global');
const last = data._last || {};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const agentText = String(j.output ?? j.text ?? j.response ?? '').trim();
  const body = agentText || (last.replyBody || 'Veredicto no disponible.');
  out.push({ json: { toRecipients: last.replyTo || '', subject: last.replySubject || 'Análisis de seguridad de su correo', bodyContent: body } });
}
return out;
